package main

import (
	"fmt"
	"time"
)

// 处理任务
func job(jobCh chan int, resCh chan int) {
	for v := range jobCh {
		// 偶数
		if v%2 == 0 {
			time.Sleep(1 * time.Second)
		} else {
			time.Sleep(3 * time.Second)
		}
		resCh <- (v * v)
	}
}

func main() {
	// 创建 channel
	jobCh := make(chan int, 5)
	resCh := make(chan int)
	peopleNum := 3
	jobNum := 5

	// 启动工人
	for i := 0; i < peopleNum; i++ {
		go job(jobCh, resCh)
	}

	// 设置超时 2s
	timeoutCh := time.After(2 * time.Second)

	// 发送任务
	for i := 0; i < jobNum; i++ {
		jobCh <- (i + 1)
	}
	close(jobCh)

	// 接收结果
	resNum := 0
	for resNum < jobNum {
		select {
		case result := <-resCh:
			fmt.Printf("recv a result: %d\n", result)
			resNum++
		case <-timeoutCh:
			fmt.Println("timeout")
			return
		}
	}

	fmt.Println("所有任务处理完毕！")
}

content_list.content:
太棒了！我们正式进入 **第二阶段：掌握 Go 的“术”（传统同步原语）**。

虽然 Channel 很优雅，但在实际开发中，当你需要保护一个**共享的复杂状态**（比如一个包含多个字段的全局配置结构体，或者一个本地缓存 Map）时，使用传统的**锁（Mutex）** 往往比用 Channel 传递数据更高效、更直接。

---

### 第一步：学习原理

#### 1. `sync.Mutex`（互斥锁）与 `sync.RWMutex`（读写锁）
*   **本质**：用于保护**临界区（Critical Section）**，确保同一时刻只有一个 Goroutine 能访问共享资源。
*   **C语言对比**：
    *   `sync.Mutex` 对应 C 语言的 `pthread_mutex_t`。
    *   `sync.RWMutex` 对应 `pthread_rwlock_t`（读锁 `RLock/RUnlock`，写锁 `Lock/Unlock`）。
*   **⚠️ C语言开发者的最大痛点（必看）：Mutex 绝对不能被复制！**
    *   在 C 语言中，结构体按值传递是家常便饭。但在 Go 中，**`sync.Mutex` 内部包含系统底层的同步状态，一旦复制（比如作为值传递的参数，或者按值接收的方法），锁就会失效，导致严重的数据竞争！**
    *   **解决方案**：在使用锁的结构体中，要么把 Mutex 放在指针里，要么在修改结构体的方法上**必须使用指针接收者 (`*Struct`)**。
*   **Go 特色语法 (`defer`)**：为了防止函数中途 `return` 或发生 `panic` 导致忘记解锁（死锁），Go 强烈推荐使用 `defer mu.Unlock()`。

#### 2. `sync.WaitGroup`（等待组）
*   **本质**：用于**等待一组 Goroutine 执行完毕**。它内部维护了一个计数器。
*   **C语言对比**：类似于循环调用 `pthread_join`，或者自己用 Mutex + 条件变量 + 计数器实现的同步机制。
*   **三大方法**：
    *   `Add(delta int)`：计数器增加（通常在启动 Goroutine 前调用）。
    *   `Done()`：计数器减 1（通常在 Goroutine 结束时调用，配合 `defer` 使用极佳）。
    *   `Wait()`：阻塞当前 Goroutine，直到计数器归零。

---

### 第二步：看示例

#### 示例 1：数据竞争的灾难（反面教材）
如果不加锁，多个 Goroutine 同时修改同一个变量，会导致结果不可预期。

```go
package main

import (
	"fmt"
	"sync"
)

// 一个不安全的计数器
type UnsafeCounter struct {
	count int
}

func (c *UnsafeCounter) Increment() {
	c.count++ // 这里不是原子操作（读、加、写三步），会发生竞争！
}

func main() {
	counter := UnsafeCounter{}
	var wg sync.WaitGroup

	for i := 0; i < 1000; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done() // 保证协程结束时计数器减 1
			for j := 0; j < 1000; j++ {
				// ⚠️ 严重错误：如果这里把 counter 按值传给函数，修改的是副本！
				// 必须传递指针 &counter
				counter.Increment() 
			}
		}()
	}

	wg.Wait() // 等待所有 1000 个协程完成
	fmt.Printf("预期结果: 1000000, 实际结果: %d\n", counter.count)
	// 实际结果往往小于 1000000，这就是数据竞争！
}
```

#### 示例 2：使用 Mutex 修复（正面教材）
引入 `sync.Mutex` 来保护临界区。

```go
package main

import (
	"fmt"
	"sync"
)

// 安全的计数器：将 Mutex 嵌入结构体
type SafeCounter struct {
	mu    sync.Mutex // 互斥锁
	count int
}

// 必须使用指针接收者 *SafeCounter，否则传入的是结构体副本，锁会被复制导致失效！
func (c *SafeCounter) Increment() {
	c.mu.Lock()         // 加锁
	defer c.mu.Unlock() // 函数退出时自动解锁（极其推荐）
	c.count++
}

func (c *SafeCounter) Value() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.count
}

func main() {
	// 使用指针创建，确保传递的始终是同一个对象和同一把锁
	counter := &SafeCounter{} 
	var wg sync.WaitGroup

	for i := 0; i < 1000; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < 1000; j++ {
				counter.Increment()
			}
		}()
	}

	wg.Wait()
	fmt.Printf("最终结果: %d\n", counter.Value()) // 稳定输出 1000000
}
```

---

### 第三步：做练习

现在轮到你实战了！这个练习将完美检验你对 **指针接收者**、**Mutex 和 WaitGroup** 的掌握程度。

