package main

import (
	"fmt"
	"time"
)

// 处理任务
func job(jobCh chan int, resCh chan int) {
	for v := range jobCh {
		// 偶数
		if v%2 == 0 {
			time.Sleep(1)
			resCh <- (v * v)
		} else {
			time.Sleep(3)
			resCh <- (v * v)
		}
	}
}

func main() {
	// 创建 channel
	jobCh := make(chan int, 5)
	resCh := make(chan int)

	// 启动工人
	peopleNum := 3
	for i := 0; i < peopleNum; i++ {
		go job(jobCh, resCh)
	}

	// 设置超时 2s
	timeoutCh := time.After(2 * time.Second)

	// 发送任务
	jobNum := 5
	for i := 0; i < jobNum; i++ {
		jobCh <- (i + 1)
	}
	close(jobCh)

	// 接收结果
	resNum := 0
	select {
	case result := <-resCh:
		fmt.Printf("recv a result: %d\n", result)
		resNum++
		if resNum == 5 {
			break
		}
	case <-timeoutCh:
		fmt.Println("timeout")
	}
}

content_list.content:
你的代码整体结构非常清晰！Channel 的创建、Worker 的启动、任务的发送和 `close` 都写得很标准，奇偶数的判断逻辑也很准确。

不过，代码中有几个关键的细节需要调整，这也是 Go 并发编程中非常容易踩坑的地方。我们来逐一 Review：

### 🔍 代码 Review 与优化建议

#### 1. `time.Sleep` 的单位陷阱
在 Go 中，`time.Sleep` 的参数单位是**纳秒 (nanoseconds)**。
`time.Sleep(1)` 几乎瞬间就会完成，无法模拟出 1 秒或 3 秒的延迟。
**修正**：必须显式指定单位，如 `time.Sleep(1 * time.Second)`。

#### 2. `select` 不是循环结构 (核心问题)
在你的代码中，`select` 语句只执行了**一次**。匹配到某个 case 并执行后，程序就会继续往下走，直接退出 `main` 函数。因此，`resNum` 永远只能加到 1，或者如果超时先触发，程序就直接结束了。
**修正**：需要用一个 `for` 循环把 `select` 包裹起来，才能持续接收多个结果。

#### 3. Goroutine 泄漏隐患
因为 `resCh` 是**无缓冲**的，如果主函数因为某种原因（比如只执行了一次 select）提前退出，Worker 执行到 `resCh <- (v * v)` 时，由于没有接收者，它会**永久阻塞**。在长期运行的服务中，这会导致内存泄漏。
**修正**：确保主函数能妥善处理所有结果，或者在超时后主动放弃接收（虽然在这个简单练习中程序退出会清理，但养成好习惯很重要）。

---

### 💡 重构后的参考代码

结合以上三点，这是符合你练习需求的正确写法。请重点关注 `for` 循环与 `select` 的结合：

```go
package main

import (
	"fmt"
	"time"
)

func job(jobCh chan int, resCh chan int) {
	for v := range jobCh {
		if v%2 == 0 {
			time.Sleep(1 * time.Second) // 修正：加上时间单位
		} else {
			time.Sleep(3 * time.Second) // 修正：加上时间单位
		}
		resCh <- (v * v)
	}
}

func main() {
	jobCh := make(chan int, 5)
	resCh := make(chan int)
	jobNum := 5

	// 启动 3 个工人
	for i := 0; i < 3; i++ {
		go job(jobCh, resCh)
	}

	// 发送任务
	for i := 0; i < jobNum; i++ {
		jobCh <- (i + 1)
	}
	close(jobCh) // 发送完毕，关闭通道，工人处理完会自动退出

	// 设置 2 秒超时
	timeoutCh := time.After(2 * time.Second)

	// 接收结果：使用 for 循环持续监听
	resNum := 0
	for resNum < jobNum {
		select {
		case result := <-resCh:
			fmt.Printf("收到结果: %d\n", result)
			resNum++
		case <-timeoutCh:
			// 只要触发一次超时，就说明剩下的任务太慢了
			fmt.Printf("处理超时！已收到 %d/%d 个结果，放弃等待。\n", resNum, jobNum)
			return // 直接退出 main 函数，未完成的 worker 会被强制终止
		}
	}

	fmt.Println("所有任务处理完毕！")
}
```

### 🧠 理解检查

在重构的代码中，`for resNum < jobNum` 配合 `select` 实现了持续监听。
**思考一下**：如果我们将 `resCh := make(chan int)` 改为 `resCh := make(chan int, 5)`（有缓冲），程序的执行行为会发生什么变化？Worker 还会因为主函数超时退出而阻塞吗？

你可以先思考这个问题，或者直接告诉我你的答案。如果你觉得第一阶段（Goroutine 与 Channel）的核心概念已经清晰，我们就可以顺利进入 **第二阶段：传统同步原语（Mutex 与 WaitGroup）** 了！

