func job(jobCh chan int, resCh chan int) {
	for v := range jobCh {
		// 偶数
		if v%2 == 0 {
			time.Sleep(1 * time.Second)
		} else {
			time.Sleep(3 * time.Second)
		}
		resCh <- (v * v)
	}
}

func main() {
	// 创建 channel
	jobCh := make(chan int, 5)
	resCh := make(chan int)
	peopleNum := 3
	jobNum := 5

	// 启动工人
	for i := 0; i < peopleNum; i++ {
		go job(jobCh, resCh)
	}

	// 设置超时 2s
	timeoutCh := time.After(2 * time.Second)

	// 发送任务
	for i := 0; i < jobNum; i++ {
		jobCh <- (i + 1)
	}
	close(jobCh)

	// 接收结果
	resNum := 0
	for resNum < jobNum {
		select {
		case result := <-resCh:
			fmt.Printf("recv a result: %d\n", result)
