package main

import (
	"fmt"
	"sync"
	"time"
)

type Cache struct {
	data map[string]int
	Mu   sync.RWMutex
}

// Set
func (c *Cache) Set(key string, value int) {
	c.Mu.Lock()
	defer c.Mu.Unlock()

	c.data[key] = value
}

// Get
func (c *Cache) Get(key string) (int, bool) {
	c.Mu.RLock()
	defer c.Mu.RUnlock()

	value, ok := c.data[key]
	return value, ok
}

func main() {
	c := &Cache{
		data: make(map[string]int),
	}
	wg := new(sync.WaitGroup)

	// 启动5对 set / get
	for i := 0; i < 5; i++ {
		wg.Add(2)
		fmt.Printf("running %d\n", i)

		// invoke set
		go func(num int) {
			defer wg.Done()
			key := fmt.Sprintf("user_%d", num)
			c.Set(key, num*num)
		}(i)

		// invoke get
		go func(num int) {
			defer wg.Done()

			time.Sleep(1 * time.Second)

			key := fmt.Sprintf("user_%d", num)
			if result, ok := c.Get(key); ok {
				fmt.Printf("Get result with %s: %d\n", key, result)
			} else {
				fmt.Printf("Get error with key %s\n", key)
			}
		}(i)
	}

	// 等待结束
	wg.Wait()

	// 打印 Cache 内容
	for key, value := range c.data {
		fmt.Printf("%s -> %d\n", key, value)
	}
}

content_list.content:
太棒了！我们正式进入 **第三阶段：并发生命周期控制（Context）**。

这是 Go 语言中最具特色、也是生产环境中最不可或缺的并发控制机制。掌握了它，你就真正具备了编写“健壮、不泄漏”的 Go 并发代码的能力。

---

### 第一步：学习原理

#### 1. 为什么需要 Context？
在 C 语言的多线程编程中，如果想中途取消一个正在运行的线程，通常需要传递一个全局的或共享的 `volatile int *cancel_flag` 标志位，线程内部不断轮询这个标志位。
在 Go 中，Goroutine 数量庞大且轻量，如果父任务（如一个 HTTP 请求）因为客户端断开而结束了，但它启动的 10 个子 Goroutine 还在后台傻傻地等待网络响应或计算，这 10 个 Goroutine 就会**永久阻塞**，导致 **Goroutine 泄漏（内存泄漏）**。

`context` 包就是 Go 官方提供的标准化解决方案。它像一棵树一样，允许你将**取消信号（Cancellation）**、**截止时间（Timeout/Deadline）**和**请求级数据（Values）** 沿着 Goroutine 的调用链层层传递。

#### 2. Context 的核心接口
所有 context 都实现了这个接口：
```go
type Context interface {
    Deadline() (deadline time.Time, ok bool) // 返回截止时间
    Done() <-chan struct{}                    // 核心！返回一个 channel，当 context 被取消或超时时，这个 channel 会被关闭
    Err() error                               // 返回 context 结束的原因（Canceled 或 DeadlineExceeded）
    Value(key any) any                        // 获取绑定在 context 上的值（慎用，仅用于请求级元数据）
}
```
*💡 重点理解 `Done()`*：在 Go 中，**关闭一个 channel** 是广播通知所有监听者的最有效方式。当 `ctx.Done()` 返回的 channel 被关闭时，所有正在 `<-ctx.Done()` 等待的 Goroutine 都会立刻被唤醒。

#### 3. 四大核心构造函数
*   `context.Background()`: **根节点**。通常用在 `main` 函数、初始化或测试中。它永远不会被取消。
*   `context.TODO()`: **占位符**。当你不确定该用哪个 context，或者函数需要 context 但当前还没有时，用它（语义上表示“以后会补上”）。
*   `context.WithCancel(parent Context)`: 返回一个子 context 和一个 `cancel` 函数。调用 `cancel()` 会立即取消该 context 及其所有子 context。
*   `context.WithTimeout(parent Context, timeout time.Duration)`: 返回一个子 context 和一个 `cancel` 函数。到达指定时间后，会自动触发取消。（最常用！）

#### ⚠️ Context 的两大铁律（必须遵守）
1. **Context 必须作为函数的第一个参数传递**，且变量名通常叫 `ctx`。例如：`func DoSomething(ctx context.Context, arg1 int)`。
2. **绝对不要把 Context 塞进结构体（Struct）里**，它应该像水流一样在函数调用间传递。

---

### 第二步：看示例

#### 示例：使用 `WithTimeout` 优雅中止慢速任务

这个例子模拟了一个耗时 5 秒的数据库查询，但我们只愿意等 2 秒。

```go
package main

import (
	"context"
	"fmt"
	"time"
)

// 模拟一个慢速的数据库查询或外部 API 调用
// 注意：ctx 必须是第一个参数！
func slowDatabaseQuery(ctx context.Context) (string, error) {
	// 模拟一个需要 5 秒才能完成的操作
	queryDone := make(chan string, 1)
	go func() {
		time.Sleep(5 * time.Second)
		queryDone <- "查询成功：用户数据"
	}()

	// 核心：使用 select 监听两个 channel
	select {
	case result := <-queryDone:
		// 正常完成
		return result, nil
	case <-ctx.Done():
		// 被取消或超时！
		// ctx.Err() 会返回 context.DeadlineExceeded 或 context.Canceled
		return "", fmt.Errorf("查询被中止，原因: %v", ctx.Err())
	}
}

func main() {
	// 1. 创建一个根 context
	ctx := context.Background()

	// 2. 派生出一个带有 2 秒超时的子 context
	// cancel 函数用于手动提前取消（虽然这里超时会自动取消，但最佳实践是声明并 defer 调用，防止内存泄漏）
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel() // 确保资源被释放

	fmt.Println("主函数：开始查询数据库...")

	// 3. 将 ctx 传递给子任务
	result, err := slowDatabaseQuery(ctx)

	if err != nil {
		fmt.Printf("主函数：查询失败 -> %v\n", err)
	} else {
		fmt.Printf("主函数：查询成功 -> %s\n", result)
	}
}
```
**运行结果**：程序会在 2 秒后立刻打印“查询失败 -> 查询被中止，原因: context deadline exceeded”，而不会傻等 5 秒。

