package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

// 处理任务
func job(ctx context.Context, wg *sync.WaitGroup, jobCh chan int, resCh chan int) {
	defer wg.Done()

	for v := range jobCh {
		var sleepTime time.Duration
		// 偶数
		if v%2 == 0 {
			sleepTime = 1
		} else {
			sleepTime = 3
		}

		timeoutCh := time.After(sleepTime * time.Second)

		select {
		case <-timeoutCh:
			resCh <- (v * v)
		case <-ctx.Done():
			fmt.Println("Work被提前中止")
			return
		}
	}
}

func main() {
	ctx := context.Background()
	var wg sync.WaitGroup

	// 设置超时 2s
	ctx, _ = context.WithTimeout(ctx, 2*time.Second)

	// 创建 channel
	jobCh := make(chan int, 5)
	resCh := make(chan int)
	peopleNum := 3
	jobNum := 5

	// 启动工人
	for i := 0; i < peopleNum; i++ {
		wg.Add(1)
		go job(ctx, &wg, jobCh, resCh)
	}

	// 发送任务
	for i := 0; i < jobNum; i++ {
		jobCh <- (i + 1)
	}
	close(jobCh)

	// 接收结果
	resNum := 0
	for resNum < jobNum {
		select {
		case result := <-resCh:
			fmt.Printf("recv a result: %d\n", result)
			resNum++
		case <-ctx.Done():
			fmt.Println("main timeout")
			goto done
		}
	}
done:
	wg.Wait()
	fmt.Println("所有任务处理完毕！")
}

package main

import (
	"fmt"
	"sync"
	"sync/atomic"
)

type ConfigManager struct {
	once   sync.Once
	loaded atomic.Bool
	config map[string]string
}

// GetConfig
func (cf *ConfigManager) GetConfig(key string) (string, error) {
	cf.once.Do(cf.loadConfig)

	if cf.loaded.Load() {
		return cf.config[key], nil
	} else {
		return "", fmt.Errorf("配置尚未加载")
	}
}

// loadConfig
func (cf *ConfigManager) loadConfig() {
	fmt.Println("Loading global config...")

	cf.loaded.Store(true)
	cf.config["app_name"] = "MyApp"
}

func main() {
	var wg sync.WaitGroup
	cf := &ConfigManager{
		config: make(map[string]string),
	}

	// 启动 5个 Goroutine
	for i := 0; i < 5; i++ {
		wg.Add(1)

		go func(num int) {
			defer wg.Done()

			if value, err := cf.GetConfig("app_name"); err != nil {
				fmt.Printf("[%d] get config error with app_name: %s", num, err)
			} else {
				fmt.Printf("[%d] app_name -> %s\n", num, value)
			}
		}(i)
	}

	wg.Wait()
}
